$rub=static fn(int$c):string=>($c<0?'−':'').number_format(abs($c)/100,2,',',' ').' ₽';
$money=static fn(?int$c):string=>$c===null?'—':(($c<0?'−':'').number_format(abs($c)/100,2,',',' ').' ₽');
$percent=static fn(?int$bp):string=>$bp===null?'—':number_format($bp/100,2,',',' ').' %';
$coefficient=static fn(?int$bp):string=>$bp===null?'—':number_format($bp/10000,2,',',' ');
$states=['missing_norm'=>'Норма не определена','planned'=>'Запланирован','blocked'=>'Заблокирован','ready'=>'Готов к расчёту','no_new_amount'=>'Нет новой суммы','completed'=>'Завершён'];
$this->registerJsFile('/pilot/assets/otiz.js',['type'=>'module','position'=>\yii\web\View::POS_END]);
ViewSupport::begin($this,$title,$identity,'otiz');
?>
<div class="fm2-otiz fm2-otiz-page">
<?= $this->render('_otiz-nav',['current'=>$mode]) ?>
<?php if($mode==='payments'): ?>
