</span></label><?=ViewSupport::select('sort',(string)$q['sort'],['default'=>'По состоянию','regnumber_asc'=>'Регномер: А–Я','regnumber_desc'=>'Регномер: Я–А'],'Сортировка')?><?=ViewSupport::select('pageSize',(string)$q['pageSize'],['25'=>'25','50'=>'50','100'=>'100'],'Показывать')?><button class="shlz-button shlz-button--primary" type="submit">Показать</button></form>
